# C++

```cpp
#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll MOD = 998244353;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;                  // 读入数组长度 n
    vector<ll> a(n+1), s(n+1);
    for(int i = 1; i <= n; i++){
        cin >> a[i];           // 读入 a[i]
        s[i] = s[i-1] + a[i];   // 计算前缀和 s[i]
    }

    __int128 maxv = 0;         // 存放最大值，用 __int128 防止中间溢出
    // 枚举中间分割点 y
    for(int y = 2; y < n; y++){
        ll T = s[y];            // 前两段总和
        // 在 s[1..y-1] 中二分查找最接近 T/2 的位置
        int p = lower_bound(s.begin()+1, s.begin()+y, T/2) - s.begin();
        // 分别尝试 p 和 p-1
        for(int d = -1; d <= 0; d++){
            int x = p + d;
            if(x >= 1 && x < y){
                // 计算三段乘积
                __int128 v = (__int128)s[x] * (T - s[x]) * (s[n] - T);
                if(v > maxv) maxv = v;
            }
        }
    }

    ll ans = (ll)(maxv % MOD);
    cout << ans << "\n";       // 输出结果
    return 0;
}
```
