        // 存放最大乘积，用于防溢出用 long double 模拟 __int128
        long maxv = 0;
        // 枚举 y
        for(int y = 2; y < n; y++){
            long T = s[y];  // 前两段总和
            // 二分查找最接近 T/2 的位置
            int l = 1, r = y;
            while(l < r){
                int mid = (l + r) >>> 1;
                if(s[mid] < T/2.0) l = mid + 1;
                else r = mid;
            }
            // 检查 l 和 l-1
            for(int d = -1; d <= 0; d++){
                int x = l + d;
                if(x >= 1 && x < y){
                    long v = s[x] * (T - s[x]) * (s[n] - T);
                    if(v > maxv) maxv = v;
                }
            }
        }
        // 输出结果
        System.out.println(maxv % MOD);
    }
