    if not data:
        return
    n = int(data[0])
    w = list(map(int, data[1:1+n]))

    # 前缀和 s[0]=0, s[i]=sum_{k=1}^{i} w_k
    s = [0] * (n + 1)
    for i in range(1, n + 1):
        s[i] = s[i-1] + w[i-1]

    total = s[n]
    MOD = 998244353
