    static final BigInteger MOD = BigInteger.valueOf(998244353);

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        long[] w = new long[n];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            w[i] = Long.parseLong(st.nextToken());
        }

        // 前缀和 s[0]=0, s[i]=sum_{k=1}^{i} w_k
        long[] s = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            s[i] = s[i-1] + w[i-1];
        }

        long total = s[n];
        BigInteger maxProd = BigInteger.ZERO;

        // 枚举第二个切割点 q （2 <= q <= n-1)
        for (int q = 2; q < n; q++) {
            long T = s[q];  // 前两段总和
            // 二分查找在 s[1..q-1] 中第一个 >= T/2 的位置
            int lo = 1, hi = q;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (s[mid] * 2 < T) {   // 使用 *2 避免浮点误差
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }
            // 检查 lo 和 lo-1
            for (int p = lo; p >= lo - 1 && p >= 1; p--) {
                if (p < q) {
                    BigInteger S1 = BigInteger.valueOf(s[p]);
                    BigInteger S2 = BigInteger.valueOf(T - s[p]);
                    BigInteger S3 = BigInteger.valueOf(total - T);
                    BigInteger prod = S1.multiply(S2).multiply(S3);
                    if (prod.compareTo(maxProd) > 0) {
                        maxProd = prod;
                    }
                }
            }
        }

        System.out.println(maxProd.mod(MOD));
    }
}
